// Calendly v2 HMAC signature verification, opt-in.
// Header: Calendly-Webhook-Signature with format `t=<unix-ts>,v1=<hmac-sha256>`
// HMAC payload: `<timestamp>.<rawBody>` (Stripe-like, not just rawBody).
//
// Enable by setting CALENDLY_SIGNING_SECRET + WEBHOOK_INTEGRITY_CHECK_ENABLED=1.
// Pass-through when unset.

const secret = $env.CALENDLY_SIGNING_SECRET;
const integrityCheckEnabled = $env.WEBHOOK_INTEGRITY_CHECK_ENABLED === '1';

if (!secret || !integrityCheckEnabled) {
  return [$input.first()];
}

const crypto = require('crypto');
const item = $input.first();
const rawBody = item.rawBody || (typeof item.body === 'string' ? item.body : JSON.stringify(item.body || {}));
const headers = item.headers || {};
const sigHeader = headers['calendly-webhook-signature'] || headers['Calendly-Webhook-Signature'];

if (!sigHeader || typeof sigHeader !== 'string') {
  throw new Error('UNAUTHORIZED: missing Calendly-Webhook-Signature header');
}

// Parse `t=<ts>,v1=<hmac>` into a map
const parts = {};
for (const segment of sigHeader.split(',')) {
  const [k, v] = segment.split('=');
  if (k && v) parts[k.trim()] = v.trim();
}
const ts = parts.t;
const v1 = parts.v1;

if (!ts || !v1) {
  throw new Error('UNAUTHORIZED: malformed Calendly signature header');
}

// Replay-window check: 5 minutes
const tsNum = parseInt(ts, 10);
if (!Number.isFinite(tsNum)) {
  throw new Error('UNAUTHORIZED: invalid timestamp');
}
const nowSec = Math.floor(Date.now() / 1000);
const REPLAY_WINDOW_S = 5 * 60;
if (Math.abs(nowSec - tsNum) > REPLAY_WINDOW_S) {
  throw new Error('UNAUTHORIZED: signature timestamp outside replay window');
}

const signedPayload = ts + '.' + rawBody;
const expected = crypto.createHmac('sha256', secret).update(signedPayload, 'utf8').digest('hex');

// Length-guard before constant-time compare
if (v1.length !== expected.length) {
  throw new Error('UNAUTHORIZED: signature length mismatch');
}

const expBuf = Buffer.from(expected, 'utf8');
const v1Buf = Buffer.from(v1, 'utf8');
if (!crypto.timingSafeEqual(expBuf, v1Buf)) {
  throw new Error('UNAUTHORIZED: invalid signature');
}

return [$input.first()];

// Per-IP sliding-window rate limit, opt-in.
// Enable by setting RATE_LIMIT_ENABLED=1.
// 60 requests per 5 minutes per IP.
//
// $getWorkflowStaticData is per-instance, not cluster-aware. Replace with
// Redis INCR + EXPIRE for multi-worker n8n. Snippet at the bottom.

if ($env.RATE_LIMIT_ENABLED !== '1') {
  return [$input.first()];
}

const LIMIT = 60;
const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 5000;

const item = $input.first();
const headers = item.headers || {};
const rawIp = headers['x-forwarded-for'] || headers['x-real-ip'] || 'unknown';
const key = String(rawIp).split(',')[0].trim();

const data = $getWorkflowStaticData('global');
data.rateBuckets = data.rateBuckets || {};
const buckets = data.rateBuckets;
const now = Date.now();

for (const k of Object.keys(buckets)) {
  buckets[k] = (buckets[k] || []).filter(t => now - t < WINDOW_MS);
  if (buckets[k].length === 0) delete buckets[k];
}
if (Object.keys(buckets).length > MAX_KEYS) {
  const oldest = Object.entries(buckets).sort((a, b) => (a[1][0] || 0) - (b[1][0] || 0)).slice(0, 100);
  for (const [k] of oldest) delete buckets[k];
}

const hits = buckets[key] || [];
if (hits.length >= LIMIT) {
  throw new Error('RATE_LIMIT_EXCEEDED: ' + LIMIT + ' requests per ' + Math.round(WINDOW_MS / 60000) + ' minutes for ' + key);
}
buckets[key] = [...hits, now];

return [$input.first()];

// Redis variant for clustered n8n:
// const Redis = require('ioredis');
// const redis = new Redis(process.env.REDIS_URL);
// const cnt = await redis.incr('rl:' + key);
// if (cnt === 1) await redis.expire('rl:' + key, 300);
// await redis.quit();
// if (cnt > LIMIT) throw new Error('RATE_LIMIT_EXCEEDED');

// 5-minute idempotency window on Calendly event.uri, opt-in.
// Enable by setting IDEMPOTENCY_ENABLED=1.
// Calendly retries on 5xx for up to 24 hours, but a 5-minute window catches
// the storm of retries that follow a recovery. The longer-tail retries
// usually arrive after the first successful processing.

if ($env.IDEMPOTENCY_ENABLED !== '1') {
  return [$input.first()];
}

const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 10000;

const item = $input.first();
const body = item.body || {};
// Calendly v2 payload: { event: 'invitee.created', payload: { event: { uri }, invitee: { uri } } }
const eventUri = body.payload && body.payload.event && body.payload.event.uri;
const inviteeUri = body.payload && body.payload.invitee && body.payload.invitee.uri;
const evtName = body.event || 'unknown';
const idempotencyKey = (eventUri && inviteeUri) ? (evtName + ':' + eventUri + ':' + inviteeUri) : null;

if (!idempotencyKey) {
  return [$input.first()];
}

const data = $getWorkflowStaticData('global');
data.seenKeys = data.seenKeys || {};
const seen = data.seenKeys;
const now = Date.now();

for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}
if (Object.keys(seen).length > MAX_KEYS) {
  const oldest = Object.entries(seen).sort((a, b) => a[1] - b[1]).slice(0, 1000);
  for (const [k] of oldest) delete seen[k];
}

if (seen[idempotencyKey]) {
  return [{ json: { skipped: true, reason: 'duplicate', idempotencyKey } }];
}
seen[idempotencyKey] = now;

return [$input.first()];

// Redis variant:
// const result = await redis.set('idem:' + idempotencyKey, '1', 'EX', 300, 'NX');
// if (result === null) return [];

// Normalize Calendly v2 nested webhook payload into a stable schema.
// Calendly v2 ships everything inside body.payload with `invitee` and `event` sub-objects.

const body = $input.first().body || {};
const eventName = body.event || 'unknown';
const payload = body.payload || {};
const event = payload.event || {};
const invitee = payload.invitee || {};
const scheduled = payload.scheduled_event || event;

const questionAnswers = Array.isArray(invitee.questions_and_answers) ? invitee.questions_and_answers : [];
const answersMap = {};
for (const qa of questionAnswers) {
  if (qa && qa.question && qa.answer != null) answersMap[String(qa.question).toLowerCase().trim()] = String(qa.answer).trim();
}

return [{
  json: {
    eventName,
    eventUri: event.uri || scheduled.uri || null,
    inviteeUri: invitee.uri || null,
    inviteeEmail: (invitee.email || '').toLowerCase(),
    inviteeName: invitee.name || invitee.first_name || 'Unknown',
    inviteeTimezone: invitee.timezone || null,
    eventTypeName: scheduled.name || event.name || 'Calendly booking',
    eventStartTime: scheduled.start_time || event.start_time || null,
    eventEndTime: scheduled.end_time || event.end_time || null,
    cancelReason: invitee.cancellation && invitee.cancellation.reason ? invitee.cancellation.reason : null,
    canceler: invitee.cancellation && invitee.cancellation.canceled_by ? invitee.cancellation.canceled_by : null,
    questionAnswers: answersMap,
    receivedAt: new Date().toISOString(),
  },
}];

// Classify the booking lifecycle and pick a CRM stage.
// Three states: booked (invitee.created), canceled (invitee.canceled), no_show (invitee.no_show).

const input = $input.first().json;
const evt = String(input.eventName || '').toLowerCase();

let lifecycle = 'unknown';
let stageEnv = 'CRM_PIPELINE_CANCELED_ID';

if (evt === 'invitee.created') {
  lifecycle = 'booked';
  stageEnv = 'CRM_PIPELINE_BOOKED_ID';
} else if (evt === 'invitee.canceled') {
  lifecycle = 'canceled';
  stageEnv = 'CRM_PIPELINE_CANCELED_ID';
} else if (evt === 'invitee.no_show') {
  lifecycle = 'no_show';
  stageEnv = 'CRM_PIPELINE_CANCELED_ID';
}

const stageId = $env[stageEnv] || '1';

return [{
  json: {
    ...input,
    lifecycle,
    stageId,
  },
}];

// Pick CRM target from env. Default pipedrive.

const input = $input.first().json;
const crmTarget = ($env.CRM_TARGET || 'pipedrive').toLowerCase();

return [{
  json: {
    ...input,
    crmTarget,
  },
}];

// Normalize CRM response so downstream does not care which CRM fired.

const input = $input.first();
const body = input.json || {};

let dealId = null;
if (body.data && body.data.id) dealId = body.data.id;
else if (body.id) dealId = body.id;

return [{
  json: {
    ...body,
    dealId,
    crmSuccess: !!dealId,
  },
}];

// Fallback for downstream API failures (Pipedrive / HubSpot / Salesforce / Slack).
// Builds a structured error log and a graceful response so Calendly sees a 200
// instead of triggering a 24-hour retry storm.

const input = $input.first();
const err = (input.json && input.json.error) || input.error || {};
const orig = ($('Set CRM Target').first() && $('Set CRM Target').first().json) || {};

return [{
  json: {
    ok: false,
    fallback: true,
    eventUri: orig.eventUri || 'unknown',
    inviteeEmail: orig.inviteeEmail || 'unknown',
    crmTarget: orig.crmTarget || 'unknown',
    lifecycle: orig.lifecycle || 'unknown',
    error: {
      message: err.message || 'unknown error',
      name: err.name || 'CalendlyCrmError',
    },
    receivedAt: orig.receivedAt || new Date().toISOString(),
  },
}];
